$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$source = Join-Path $repoRoot '.deps/dxvk-remix'
. (Join-Path $source 'bridge/build_common.ps1')
$testDir = Join-Path $repoRoot '.deps/readback-test'
New-Item -ItemType Directory -Force $testDir | Out-Null
Push-Location $testDir
try {
  SetupVS -Platform x64 -VcVarsVer '14.29'
  & cl.exe /nologo /std:c++17 /EHsc /W4 /WX "/I$source/bridge/src/server" "/I$source/bridge/src/client" "/I$source/bridge/src/util" "$repoRoot/tests/readback_recovery.cpp" /Fe:readback-server.exe /link bcrypt.lib
  if ($LASTEXITCODE -ne 0) { throw 'x64 readback test compilation failed' }
  SetupVS -Platform x86 -VcVarsVer '14.29'
  & cl.exe /nologo /std:c++17 /EHsc /W4 /WX "/I$source/bridge/src/util" "$repoRoot/tests/readback_layout.cpp" /Fe:readback-layout.exe
  if ($LASTEXITCODE -ne 0) { throw 'Readback layout test compilation failed' }
  & ./readback-layout.exe
  if ($LASTEXITCODE -ne 0) { throw "Readback layout test failed: $LASTEXITCODE" }
  & cl.exe /nologo /std:c++17 /EHsc /W4 /WX "/I$source/bridge/src/server" "/I$source/bridge/src/client" "/I$source/bridge/src/util" "$repoRoot/tests/readback_recovery.cpp" /Fe:readback-client.exe /link bcrypt.lib
  if ($LASTEXITCODE -ne 0) { throw 'x86 readback test compilation failed' }
  & ./readback-client.exe (Join-Path $testDir 'readback-server.exe')
  if ($LASTEXITCODE -ne 0) { throw "Cross-process readback test failed: $LASTEXITCODE" }
} finally { Pop-Location }
